package com.example.starter.model;

import java.time.LocalDateTime;

/**
 * 缺陷记录行：巡检按叶片与位置登记，detectedAt 为首次缺陷登记时刻(UTC)。
 */
public record DefectRow(
        long id,
        long bladeId,
        String bladePosition,
        DefectLevel defectLevel,
        String defectType,
        LocalDateTime detectedAt) {
}

package com.example.starter.model;

import java.time.LocalDateTime;

/**
 * 维修单行：status IN_PROGRESS/CLOSED；closeResult ON_TIME/LATE，未结案为 null。
 */
public record RepairOrderRow(
        long id,
        long defectId,
        long bladeId,
        String status,
        LocalDateTime deadlineAt,
        LocalDateTime closedAt,
        String closeResult,
        boolean escalated) {

    public boolean inProgress() {
        return "IN_PROGRESS".equals(status);
    }
}

package com.example.starter.model;

import java.time.LocalDateTime;

/**
 * 限功率链行：revokedAt 为 null 表示仍生效。
 */
public record PowerLimitRow(
        long id,
        long bladeId,
        String reason,
        LocalDateTime startedAt,
        LocalDateTime revokedAt) {

    public boolean active() {
        return revokedAt == null;
    }
}

package com.example.starter.model;

import java.time.LocalDateTime;

/**
 * 根因评估行：status IN_PROGRESS/COMPLETED。
 */
public record AssessmentRow(
        long id,
        long bladeId,
        String defectType,
        int triggerCount,
        String status,
        LocalDateTime startedAt,
        LocalDateTime completedAt) {
}

package com.example.starter.model;

import java.time.LocalDateTime;

/**
 * 逾期升级告警行：保留首次缺陷登记时刻 firstDetectedAt。
 */
public record AlertRow(
        long id,
        long repairOrderId,
        long bladeId,
        long defectId,
        LocalDateTime firstDetectedAt,
        LocalDateTime alertAt,
        String message) {
}

package com.example.starter.model;

/**
 * 幂等记录行：responseBody 为首次成功响应快照。
 */
public record IdempotencyRow(
        String requestId,
        String endpoint,
        String fingerprint,
        String responseBody) {
}

package com.example.starter.model;

import java.time.LocalDateTime;

/**
 * 同类缺陷复发聚合行：90 日窗口内按缺陷类别统计。
 */
public record RecurrenceAgg(
        String defectType,
        long count,
        LocalDateTime firstDetectedAt,
        LocalDateTime lastDetectedAt) {
}

