package com.example.starter.dto;

import com.example.starter.model.DefectLevel;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDateTime;

/**
 * 缺陷登记请求。detectedAt 为空时取当前时刻(UTC)。
 */
public record CreateDefectRequest(
        @NotBlank String requestId,
        @NotNull Long bladeId,
        @NotBlank String bladePosition,
        @NotNull DefectLevel defectLevel,
        @NotBlank String defectType,
        LocalDateTime detectedAt) {
}

package com.example.starter.dto;

import com.example.starter.model.DefectLevel;
import java.time.LocalDateTime;

/**
 * 缺陷登记响应：包含登记后派生的限功率与根因评估状态。
 */
public record DefectResponse(
        long id,
        long bladeId,
        String bladePosition,
        DefectLevel defectLevel,
        String defectType,
        LocalDateTime detectedAt,
        boolean powerLimitActive,
        boolean assessmentTriggered,
        Long assessmentId) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 维修单创建请求：一张维修单对应一条缺陷记录。
 */
public record CreateRepairOrderRequest(
        @NotBlank String requestId,
        @NotNull Long defectId) {
}

package com.example.starter.dto;

import java.time.LocalDateTime;

/**
 * 维修单视图：维修台账条目，closeResult 未结案为 null。
 */
public record RepairOrderView(
        long id,
        long defectId,
        long bladeId,
        String status,
        LocalDateTime deadlineAt,
        LocalDateTime closedAt,
        String closeResult,
        boolean escalated) {
}

package com.example.starter.dto;

import com.example.starter.model.ReinspectionResult;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 复检登记请求：复检合格则同事务结案并撤销限功率，不合格则维持限功率。
 */
public record CreateReinspectionRequest(
        @NotBlank String requestId,
        @NotNull ReinspectionResult result) {
}

package com.example.starter.dto;

import com.example.starter.model.ReinspectionResult;
import java.time.LocalDateTime;

/**
 * 复检登记响应：包含复检后维修单状态与限功率状态。
 */
public record ReinspectionResponse(
        long id,
        long repairOrderId,
        ReinspectionResult result,
        LocalDateTime inspectedAt,
        String orderStatus,
        boolean powerLimitActive) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 根因评估完成请求。
 */
public record CompleteAssessmentRequest(
        @NotBlank String requestId) {
}

package com.example.starter.dto;

import java.time.LocalDateTime;

/**
 * 根因评估视图。
 */
public record AssessmentView(
        long id,
        long bladeId,
        String defectType,
        int triggerCount,
        String status,
        LocalDateTime startedAt,
        LocalDateTime completedAt,
        boolean powerLimitActive) {
}

package com.example.starter.dto;

import java.time.LocalDateTime;

/**
 * 限功率链视图：active 表示当前生效。
 */
public record PowerLimitView(
        long id,
        long bladeId,
        String reason,
        LocalDateTime startedAt,
        LocalDateTime revokedAt,
        boolean active) {
}

package com.example.starter.dto;

import java.time.LocalDateTime;

/**
 * 逾期升级告警视图：保留首次缺陷登记时刻。
 */
public record AlertView(
        long id,
        long repairOrderId,
        long bladeId,
        long defectId,
        LocalDateTime firstDetectedAt,
        LocalDateTime alertAt,
        String message) {
}

package com.example.starter.dto;

import java.time.LocalDateTime;

/**
 * 同类缺陷复发统计视图：按缺陷类别聚合，窗口可复算。
 */
public record RecurrenceStatView(
        String defectType,
        long count,
        LocalDateTime windowStart,
        LocalDateTime windowEnd,
        LocalDateTime firstDetectedAt,
        LocalDateTime lastDetectedAt) {
}

package com.example.starter.dto;

import java.util.List;

/**
 * 逾期升级扫描响应：本次新增的升级告警列表（重复执行幂等，不重复告警）。
 */
public record EscalateResponse(
        int escalatedCount,
        List<AlertView> alerts) {
}

