    public List<PowerLimitRow> listByBlade(long bladeId) {
        return jdbc.query(
                "SELECT id, blade_id, reason, started_at, revoked_at FROM power_limit"
                        + " WHERE blade_id = ? ORDER BY started_at, id",
                ROW_MAPPER, bladeId);
    }
}

